INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_071', 'be-071', 'Танец теней', 'Наносит 1 ед. урона всем противникам с полным здоровьем.', 'НОГИ В ПЛЯС, ГОЛОВУ С ПЛЕЧ!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_071.png', 'Juan Calle', 0, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_142', 'be-142', 'Боевой марш', 'Все параметры этой карты равны вашей оставшейся мане. Призывает солдата 1/1 с <b>«Божественным щитом»</b>.', 'Земельники маршируют строем 1000 на 1000. Раз-два, раз-два!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_142.png', 'BOSi Studio', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_193', 'be-193', 'Газовый скат', '<b>Яд</b>', 'Не кормите его бобовыми.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_193.png', 'Slawomir Maniak', 1, 1, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_255', 'be-255', 'Доисторический змей', 'После того как вы разыгрываете существо,& получает +1 к здоровью.', '.ынам мордев с енидеан хи етйялватсо ен ешчул ,ызоргу йошьлоб тюялватсдерп ен ино ятоХ .йеигренэ йоксйедорач ястюатип иемз итЭ', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_255.png', 'Tee Fuyuan', 1, 2, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_223', 'be-223', 'Древнее слово: свежевание', 'Наносит 3 ед. урона случайному противнику. <i>(Следующее заклинание Тьмы, которое вы разыграете, повторит этот эффект!)</i>', 'При произношении древних слов самое главное — не ошибиться в переводе.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_223.png', 'Ivo Campelo da Silva', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_558', 'be-558', 'Каменная рукавица', 'После того как ваш герой атакует, преобразует 5 ед. здоровья героя в броню.', 'Ладно, сделаю все сам.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_558.png', 'Studio Hive', 1, 2, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_588', 'be-588', 'Мимирон', '<b>Боевой клич:</b> если у вас есть механизм, вы <b>раскапываете</b> идеальную «техническую» карту.', '.»меинеГ« ябес лисалгзоворп но оготэ елсоП .амонг огоксечинахем огонвиткаен в ьсалитсемереп аноримиМ ашуд ,онежотчину олыб олет оге адгоК .аноримиМ ьтсоньлетат', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_588.png', 'Zoltan Boros', 1, 2, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_094', 'be-094', 'Обучение воздухоплаванию', 'Существо на поле и случайное существо в руке получают характеристики, равные удвоенной стоимости этой карты.', 'Просто верь в себя!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_094.png', 'Matt Dixon', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_302', 'be-302', 'Огненный шок', 'Наносит 2 ед. урона 2 разным противникам. <b>Перегрузка:</b> (1).', 'Обжегшись на молоке... поджигают все остальное.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_302.png', 'Ivo Campelo da Silva', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_720', 'be-720', 'Проходчик зала выводка', '<b>Боевой клич:</b> вы получаете личинку за (1) с <b>«Серией приемов»</b>, которая применяет силу героя другого класса.', 'Любит копаться в земле, а еще в файлах игры.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_720.png', 'Vladimir Kafanov', 1, 1, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_220', 'be-220', 'Разлом энтропии', 'Вы получаете 2 случайных заклинания Тьмы.', 'Если долго вглядываться в Бездну... Бездна подмигнет.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_220.png', 'Luke Mancini', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_228', 'be-228', 'Служитель Зурамата', '<b>Боевой клич:</b> накладывает <b>немоту</b> на существо.', 'Моего господина не удержать!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_228.png', 'Rafael Zanchetin', 1, 1, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_566', 'be-566', 'Червивый ползун', '<b>Боевой клич:</b> вы выбираете карту в руке и замешиваете ее в колоду. Она стоит на (1) меньше.', 'Любимая еда ночнокрылов.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_566.png', 'Vika Yarova', 1, 3, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_250', 'be-250', 'Диски Норганнона', 'Помещает все заклинания в вашей колоде на верх. Каждый ход вы решаете, взять ли карту из начала или конца колоды.', 'Хоть кто-то использует подставки для стаканов!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_250.png', 'Tanamaes Leejierasaes', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_325', 'be-325', 'Зловещее присутствие', 'Уничтожает существо и передает его здоровье владельцу.', '«Это не то, о чем вы подумали! Меня едят!»', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_325.png', 'Slawomir Maniak', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_801', 'be-801', 'Расцветание', 'Вы берете другое заклинание. Если это заклинание природы, оно применяется дважды.', '»Протопан12дареЛн« + ,нул-йщЮ ьсаляагтсяод ьтсозрт аштэ м4отъоП .атоЗ/''Н ын)ревкс то асел ьти(тс+Ци-чво ыьбс2отчт ,еуйр5иГм им,оучп', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_801.png', 'Vika Yarova', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_208', 'be-208', 'Титанические размеры', 'Вы берете существо. Звери у вас в руке получают +2/+2.', 'Маленький лис окинул взглядом мир, чувствуя себя королем.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_208.png', 'Eva Widermann', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_561', 'be-561', 'Горн созидания', 'Призывает голема 3/3 с <b>«Провокацией»</b>. Вы расходуете 3 ед. брони, и он получает +3/+3.', 'Этот горн вместе изобрели Аркедас и Мимирон, чтобы восстановить поврежденную душу мира. Это устройство также хранит силу, способную стереть и воссоздать всю жизнь на Азероте.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_561.png', 'BOSi Studio', 3, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_000', 'be-000', 'Зов Света', '<b>Похищение жизни</b>. Восполняет здоровье обоим игрокам.', 'Свет, выходи поиграть!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_000.png', 'Melvin Chan', 3, 4, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_227', 'be-227', 'Клинок Темной Империи', 'Если вы применили заклинание Тьмы, в конце вашего хода противник получает урон от усталости. В противном случае его получаете вы.', 'Ксал''атат на протяжении многих веков попадала в руки легендарных героев. Они не обрели бы такой славы, если бы не помощь проклятого клинка.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_227.png', 'Tanamaes Leejierasaes', 3, 0, NULL, 3, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_251', 'be-251', 'Космические источники', 'Вы берете карту. Если это не существо, вы восстанавливаете 2 кристалла маны.', 'Здесь можно набрать чистой космической воды во время межзвездных перелетов.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_251.png', 'BOSi Studio', 3, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_552', 'be-552', 'Огнеплюй', 'После того как ваш герой атакует,& вы получаете «Форсаж».', 'Наносит раны и тут же прижигает их.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_552.png', 'Mauricio Herrera', 3, 3, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_780', 'be-780', 'Ульдирский карантин', 'Заблокировано до тех пор, пока вы не разыграете карту с каждой руной. Призывает случайное существо за (5).', 'Если я хоть что-то понимаю в компьютерных играх, нам нужно открыть эти двери, победить находящихся за ними боссов и собрать мощные предметы, чтобы открыть секретную концовку.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_780.png', 'BOSi Studio', 3, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_349', 'be-349', 'Окулярный молот', 'После того как ваш герой атакует,& призывает двух элементалей 2/2 с <b>«Натиском»</b>.', 'Берегите зрение своего молота.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_349.png', 'Studio Hive', 4, 2, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('BE_771', 'be-771', 'Хлыст-щупальце', 'После того как ваш герой атакует, уменьшает стоимость К''Туна на (1). Вы выбираете и применяете способность К''Туна.', 'К''Тун наделил меня своей мощью!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/BE_771.png', 'Studio Hive', 5, 1, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'BE'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_201', 'jail-201', 'Секретный ингредиент', '<b>Выберите эффект:</b> ваш герой получает +2 к атаке до конца хода или вы получаете случайную карту друида.', 'Глаз тритона, лапка лягушки, рука... еще чья-то.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_201.png', 'Brian Adriel', 0, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_386', 'jail-386', 'Борьба за снаряжение', 'Вы получаете +2 к броне и замешиваете в колоду пять карт снаряжения. Когда вы берете эти карты, вы получаете +2 к броне.', 'Это словно готовить маленького ребенка к выходу из дома.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_386.png', 'Sonderflex', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_501', 'jail-501', 'Взломщик', 'Все параметры этой карты равны вашей оставшейся мане. <b>Боевой клич:</b> наносит 1 ед. урона существу противника.', 'Сейчас посмотрим, где хранится вся ваша мана...', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_501.png', 'Eva Widermann', 1, 1, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_732', 'jail-732', 'Душа Бездны', 'Призывает случайного демона за (1). Улучшает будущие «Души Бездны».', 'ВНИМАНИЕ: в случае неполадок ваша душа попадет в Бездну.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_732.png', 'Tee Fuyuan', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_442', 'jail-442', 'Замаскированный врач', 'Можно разыграть с любой стороны поля. <b>Предсмертный хрип:</b> замешивает в вашу колоду 4 карты «Гниль», которые наносят 2 ед. урона при взятии.', 'Доктор на месте... инкогнито!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_442.png', 'Timur Shevtsov', 1, 5, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_452', 'jail-452', 'Замаскированный детектив', 'Можно разыграть с любой стороны поля. Этот игрок также получает <b>«Перегрузку»</b> (2).', 'Ну, мне пора. Ах да, еще кое-что...', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_452.png', 'Max Grecke', 1, 4, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_319', 'jail-319', 'Ключ-отмычка', 'Вы <b>раскапываете</b> заклинание. Предложенные варианты можно обновлять <i>(каждый раз с вероятностью 20% получая 5 ед. урона!)</i>', 'Скелет принадлежит тому, кто пытался использовать этот ключ в прошлый раз.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_319.png', 'Kevin Sidharta', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_380', 'jail-380', 'Контрабандная лопата', '<b>Предсмертный хрип:</b>& вы берете заклинание, которого не было в вашей колоде в начале матча.', 'Копать от забора и до заката.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_380.png', 'Tanamaes Leejierasaes', 1, 1, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_987', 'jail-987', 'Небезопасная секция', 'Вы получаете случайное существо шамана. Оно блокируется в вашей руке, пока вы не разыграете другую карту.', 'Не то чтобы эти прислужники не стоили внимания стражников. Просто стражники сейчас немного заняты.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_987.png', 'BOSi Studio', 1, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_202', 'jail-202', 'Паучок', 'Ваш герой получает +1 к атаке до конца вашего хода.', 'Да, шеф!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_202.png', 'Matt Dixon', 1, 1, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_940', 'jail-940', 'Посмертный приговор', 'Активирует <b>«Предсмертный хрип»</b> вашего случайного существа, погибшего в этом матче.', 'Наказание только для самых бессердечных преступников.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_940.png', 'Jason Kang', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_880', 'jail-880', 'Смотритель черного рынка', 'Когда вы разыгрываете любое существо с <b>«Предсмертным хрипом»</b>, оно получает <b>«Натиск»</b>.', 'Вы уже зарегистрировались на черном рынке? Если вы создадите учетную запись сейчас, вы получите скидку 20% на первый ящик украденных товаров!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_880.png', 'Sergey Tsvelykh', 1, 1, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_125', 'jail-125', 'Холодная хватка', '<b>Замораживает</b> противника. Вы получаете случайное заклинание льда.', 'С такой хваткой лучше избегать рукопожатий.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_125.png', 'Tee Fuyuan', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_376', 'jail-376', 'Ядро на цепи', '<b>Предсмертный хрип:</b>& ваши существа с неполным здоровьем получают +1/+2.', 'Сколько это может продолжаться?! Судя по всему, на протяжении трех описаний.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_376.png', 'Juan Calle', 1, 1, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_997', 'jail-997', 'Демоническое сдерживание', 'Погружает существо в <b>спячку</b> на 2 хода. Если это ваш демон, вместо этого он получает +3/+3.', 'Где поместился, там и поселился.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_997.png', 'Stefan Bogdasarov', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_877', 'jail-877', 'Сеть Клоаки', 'Призывает крысу 2/1 со свойством «<b>Предсмертный хрип:</b> вы берете карту».', 'Сыр? Мне это надо!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_877.png', 'Grace Liu', 2, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_450', 'jail-450', 'Трупная пушка', 'После того как ваш герой атакует,& призывает хрупкого вурдалака 1/1.', 'Наши трупы закроют вам солнце!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_450.png', 'Daniil Kudriavtsev', 2, 1, NULL, 3, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_503', 'jail-503', 'Кнут Черной Лапы', 'Стоит на (1) меньше за каждую монетку в вашей руке. <b>Предсмертный хрип:</b> вы берете карту.', 'Монетка. Кнут. Сдаться.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_503.png', 'Ramzy Kamen', 3, 3, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_379', 'jail-379', 'Охранник шпиля', '<b>Боевой клич:</b> вы показываете заклинание из вашей колоды. Если оно стоит (5) или больше,& распределяет 5 ед. урона между существами противника.', 'Нельзя так просто выйти из Аметистовой крепости. Ее врата стережет не только клан Тяжелого Кулака: там всегда начеку неспящее зло, а великое око охранника шпиля видит все.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_379.png', 'Daniil Kudriavtsev', 3, 3, 4, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_730', 'jail-730', 'Коса Звездной Пыли', 'После того как ваш герой атакует,& вы получаете «Душу Бездны».', 'А разве не любая пыль — звездная?', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_730.png', 'Dmitry Bolotov', 4, 3, NULL, 3, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_458', 'jail-458', 'Маленький дружок', '<b>Боевой клич:</b> вы выбираете стихийные боеприпасы! <i>(После того как ваш герой атакует, вы меняете боеприпас.)</i>', 'ПОРА ЗДОРОВАТЬСЯ!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_458.png', 'Studio Hive', 4, 2, NULL, 3, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_875', 'jail-875', 'Посох коварства', 'После того как ваш герой атакует, вы <b>раскапываете</b> карту друида. Ее стоимость уменьшается на атаку вашего героя.', '«Озарение» — вещь коварная. Не приходит, когда нужнее всего.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_875.png', 'Tanamaes Leejierasaes', 4, 1, NULL, 4, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_887', 'jail-887', 'Темница Зурамата', 'Вы сбрасываете карту и призываете темницу 5/5 с <b>«Провокацией»</b>. <b>Предсмертный хрип:</b> освобождает Зурамата, который разыгрывает эту карту каждый ход!', 'ПЕРЕХОЖУ В РЕЖИМ ПЫЛЕСОСА!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_887.png', 'BOSi Studio', 5, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_511', 'jail-511', 'Шпиль Уединения', 'Призывает демона с характеристиками, равными количеству карт в вашей руке. Он атакует случайное существо противника.', 'Мечта интроверта!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_511.png', 'BOSi Studio', 5, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('JAIL_329', 'jail-329', 'Искатель истины', 'После того как ваш герой атакует, ваши существа паладина получают +2/+2.', 'ПРАВДА ТЕБЕ НЕ ПО ЗУБАМ!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/JAIL_329.png', 'Vlad Botos', 7, 3, NULL, 3, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'JAIL'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_200', 'cata-200', 'Агент Древних', '<b>Боевой клич:</b> выберите карту в руке. Она превращается в монетку.', 'Времена нынче опасные, смотри в оба. И вот тебе еще один глаз.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_200.png', 'Vlad Botos', 1, 2, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_484', 'cata-484', 'Дракончик Зимних Ключей', '<b>Боевой клич:</b>& вы <b>раскапываете</b> заклинание любого класса за (1).', 'Когда встаешь на крыло, важно изучить остальные классы!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_484.png', 'Matt Dixon', 1, 1, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_556', 'cata-556', 'Дракончик-носильщик', '<b>Боевой клич:</b>& вы получаете случайного дракона за (3) или меньше.', 'Так вот откуда берутся дракончики...', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_556.png', 'Tanamaes Leejierasaes', 1, 1, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_302', 'cata-302', 'Излечение', 'Восполняет существу полный запас здоровья. Вы берете карту.', 'С тобой все в порядке... все хорошо, маме ничего не рассказывай.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_302.png', 'Ivan Fomin', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_558', 'cata-558', 'Командир подкрепления', '<b>Неуловимость</b>', 'Минуточку, это же не «Поля сражений»!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_558.png', 'Stefan Bogdasarov', 1, 2, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_130', 'cata-130', 'Кристаллоспин-детеныш', 'Когда вы тратите последний кристалл маны,& получает +1/+1.', 'Рачительности надо учиться смолоду.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_130.png', 'Vika Yarova', 1, 1, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_485', 'cata-485', 'Ледяной дождь', 'Наносит 2 ед. урона. Наносит 1 ед. урона случайному существу противника.', 'Карманный снежок!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_485.png', 'Gabriel Lopes', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_528', 'cata-528', 'Печать морей', 'В начале вашего следующего хода& призывает нагу 3/3 с <b>«Провокацией»</b>.', 'А потом приползли наги и всем нагадили.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_528.png', 'Edgar Hidalgo', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_301', 'cata-301', 'Рубиновое святилище', 'Следующий исцеляющий эффект на этом ходу не восполняет здоровье, а наносит урон.', 'А дома лучше!..', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_301.png', 'Bima Kusuma', 1, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_554', 'cata-554', 'Рык земли', 'Здоровье существа противника становится равно 1. Если у вас в руке есть дракон, вы можете выбрать еще одну цель.', '— Камни!!!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_554.png', 'Trent Kaniuga', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_210', 'cata-210', 'Сумеречное яйцо', '<b>Предсмертный хрип:</b> призывает дракончика {0}/{1}. <i>(Получает +1/+1 в начале каждого вашего хода!)</i>', 'Гм. А это еще что такое?', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_210.png', 'Felideus Bubastis', 1, 0, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_136', 'cata-136', 'Триумф Азшары', 'Вы замешиваете в свою колоду 5 случайных существ за (8) или больше. Их характеристики удваиваются.', 'Когда казалось, что победа уже у нее в руках, Владычица Океана столкнулась с самой неожиданной соперницей: героиней, которой она сама могла бы стать, если бы заботилась о своем народе.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_136.png', 'Tee Fuyuan', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_621', 'cata-621', 'Триумф Гелбина', 'Вы получаете случайную «Ауру» паладина. Она действует на один ход дольше.', 'Лорд Виктор Нефарий считал себя величайшим изобретателем Азерота, но Гелбин показал ему, что такое подлинные инновации!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_621.png', 'Max Grecke', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_585', 'cata-585', 'Факел', 'Наносит 8 ед. урона раненому существу. Возвращается в руку с силой заклинания, равной избыточному урону.', 'Не забудьте надеть железные рукавицы.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_585.png', 'Jason Kang', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_180', 'cata-180', 'Воин''лок', '<b>Боевой клич:</b> ваш следующий мурлок за (3) или меньше расходует здоровье, а не ману.', 'Твои мрррглы будут моими!!!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_180.png', 'Max Grecke', 2, 1, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_472', 'cata-472', 'Воодушевляющий молот', '<b>Предсмертный хрип:</b> активирует эффект конца хода вашего случайного существа.', 'Когда я вижу эту кувалду, я чувствую вдохновение! Хочется жить, работать и крушить черепа.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_472.png', 'Tanamaes Leejierasaes', 2, 2, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_477', 'cata-477', 'Драконьи чертоги', 'Выберите существо в руке. Оно получает +2/+2.', 'Следите за тем, чтобы в них всегда был хотя бы один дракон.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_477.png', 'BOSi Studio', 2, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_467', 'cata-467', 'Управление клешней', 'После того как ваш герой атакует, ваше случайное существо получает +2 к атаке.', 'Не щелкай клювом! Щелкай клешней!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_467.png', 'Studio Hive', 2, 2, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_584', 'cata-584', 'Извергающийся вулкан', 'Наносит 3 ед. урона, распределяемого между противниками. Если вы разыграли заклинание огня на этом ходу, наносит еще 3 ед. урона.', 'Красиво, но лучше любоваться издалека.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_584.png', 'Mooncolony', 3, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_580', 'cata-580', 'Катастрофический боевой топор', '<b>Боевой клич:</b> <b>возвещает</b>, что скоро явится {0}.', 'Очень неудобная раскаленная рукоять.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_580.png', 'Studio Hive', 3, 3, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_527', 'cata-527', 'Неспира Порабощенная', 'Наносит 1 ед. урона. После того как вы применяете заклинание Скверны, открывается снова. <b>Предсмертный хрип:</b> призывает Неспиру Освобожденную.', 'Настоящие фанаты говорят, что на самом деле она Неспира Подневольная, да и то вопрос времени.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_527.png', 'Todd Harris', 3, NULL, 5, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_492', 'cata-492', 'Сумеречное святилище', '<b>Возвещает</b>, что скоро явится {0}. Вы берете карту.', 'Здесь Чо''Галл хранит мерч, связанный с Древними богами.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_492.png', 'BOSi Studio', 4, NULL, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_722', 'cata-722', 'Глашатай конца времен', '<b>Провокация</b> <b>Боевой клич:</b> <b>возвещает</b>, что скоро явится {0}!', 'Аспекты не жалели сил и многого добились... но в итоге ничто не имело значения.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_722.png', 'Jason Kang', 5, 5, 4, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_497', 'cata-497', 'Ультраксион', '<b>Боевой клич:</b> <b>возвещает</b>, что скоро явится {0}. Уменьшает стоимость Смертокрыла на ({1}). <i>(<b>Возвестите</b>, чтобы улучшить!)</i>', 'Еще пара лет, и его будут звать Ультрагигаксион.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_497.png', 'Mooncolony', 6, 6, 7, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('CATA_190h', 'cata-190h', 'Смертокрыл Разрушитель миров', '<b>Боевой клич:</b> вы выбираете и обрушиваете {0} |4(катаклизм,катаклизма,катаклизмов)! <i><b>Возвестите</b> дважды, чтобы улучшить.</i>', 'Уничтожив Азерот в своей временной линии, Смертокрыл намерен повторить это в нашей и всех остальных, пока не останется ничего.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/CATA_190h.png', 'Alex Horley Orlandelli', 10, NULL, 30, NULL, 12, TRUE, (SELECT id FROM card_sets WHERE source_code = 'CATA'), (SELECT id FROM card_types WHERE code = 'HERO'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_218', 'time-218', 'Статический разряд', 'Наносит 1 ед. урона существу. Ваш герой получает +1 к атаке до конца хода.', 'Перед тем как пойти в бой, он долго трет ногами по ковру.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_218.png', 'Luca Zontini', 0, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_876', 'time-876', 'Бесформенный', 'Находясь в руке, каждый ход превращается в случайное существо из руки противника.', 'Не круглый, не квадратный и даже не ромбовидный...', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_876.png', 'Todd Harris', 1, 1, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_613', 'time-613', 'Герой в криостазисе', '<b>Предсмертный хрип:</b>& вы получаете случайное <b>легендарное</b> существо. Его стоимость уменьшается на (1).', 'Лучше не корчить рожицы в момент перехода в криостазис.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_613.png', 'Kevin Sidharta', 1, 2, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_212', 'time-212', 'Громоотвод', 'Наносит 2 ед. урона вашему существу и 4 ед. урона случайному существу противника.', 'Он хотел называться «Грозовым Разрядником», но так тоже сойдет.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_212.png', 'Brian Adriel', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_039', 'time-039', 'Дежавю', 'Вы <b>раскапываете</b> копию карты из руки противника.', '«Я в эти игры уже играл!»', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_039.png', 'Kevin Sidharta', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_006', 'time-006', 'Зеркальное измерение', 'Призывает существо 0/4 с <b>«Провокацией»</b>. Если у вас в руке есть дракон, призывает еще одно.', 'Также призывает двух существ 4/0.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_006.png', 'Kevin Sidharta', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_606', 'time-606', 'Кель''дорайский мастер луков', 'Когда в вашей руке 3 карты или меньше, ваша сила героя стоит (0).', 'Время летит так быстро, когда вы бьете в лицо.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_606.png', 'Tee Fuyuan', 1, 1, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_058', 'time-058', 'Неприметная пухокрылка', '<b>Предсмертный хрип:</b> призывает случайное существо за (2). Оно впадает в <b>«Спячку»</b> на 2 хода.', 'Берегитесь эффекта пухокрылки!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_058.png', 'Tanamaes Leejierasaes', 1, 1, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_EVENT_999', 'time-event-999', 'Пески времени', '<b>Перемотка:</b> вы <b>раскапываете</b> заклинание любого класса. <i>(Или только вашего класса после <b>«Перемотки»</b>!)</i>', 'Песок не сахарный. Не добавляйте его в еду.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_EVENT_999.png', 'Melvin Chan', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_447', 'time-447', 'Слово силы: Барьер', 'Цель получает <b>«Божественный щит»</b>. Существа в вашей руке получают +2 к здоровью.', 'Командная работа — это когда вы прячетесь в желтом щите и игнорируете игровые механики.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_447.png', 'Ramzy Kamen', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_701', 'time-701', 'Управление волнами', 'Вы <b>раскапываете</b> карту из колоды и кладете остальные в конец колоды.', 'Море волнуется раз...', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_701.png', 'Sergey Tsvelykh', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_444', 'time-444', 'Хроноаномальная глефа', '<b>Предсмертный хрип:</b>& вы получаете случайного демона из прошлого.', 'А, так вот в каком она времени!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_444.png', 'Daniil Kudriavtsev', 1, 2, NULL, 2, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'WEAPON'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_026', 'time-026', 'Энтропическая последовательность', 'Ваши существа получают +1/+1. Вы замешиваете в колоду 2 «Обрывка времени».', 'Подождите, это не тропическая последовательность?', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_026.png', 'Zoltan Boros', 1, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'RARE'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_707', 'time-707', 'Альтернативная реальность', 'Заменяет карты в вашей руке и колоде на случайные карты с <b>«Выбором эффекта»</b> из прошлого. Они стоят на (1) меньше.', 'Я отвергаю вашу реальность и навязываю свою!', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_707.png', 'Jakub Kasper', 2, NULL, NULL, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'SPELL'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_020', 'time-020', 'Броксигар', '<b>Герой саги. Рывок</b>. <b>Начало матча:</b> исчезает. Убейте всех 4 демонов с Аргуса, чтобы он снова появился в вашей руке.', 'Подвиг Броксигара — ранить самого Саргераса в отчаянной битве — остается величайшим достижением героев-орков.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_020.png', 'Luca Zontini', 2, 12, 12, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_061', 'time-061', 'Вневременная причинность', '<b>Боевой клич:</b> сортирует вашу колоду в обратном порядке.', 'Не путайте вневременную причинность с вневременной корреляцией.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_061.png', 'Stefan Bogdasarov', 2, 3, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_706', 'time-706', 'Вневременный Плавник', '<b>Боевой клич:</b> ваша рука заменяется на стартовую. В конце вашего хода она меняется обратно.', 'Карты? Там, куда мы идем, карты не нужны.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_706.png', 'Max Grecke', 2, 2, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_044', 'time-044', 'Гномреган: прошлое', 'Существо получает +2/+1. <i>Переходит в настоящее!</i>', 'До вторжения троггов Гномреган был процветающим технологичным мегаполисом.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_044.png', 'Kevin Sidharta', 2, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_428', 'time-428', 'Древний мурлок', 'В конце вашего хода& другие ваши существа получают +1 к здоровью.', '*ностальгические мррглы*', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_428.png', 'Tanamaes Leejierasaes', 2, 3, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_015', 'time-015', 'Жесткосветный защитник', '<b>Божественный щит</b>. <b>Боевой клич:</b> восстанавливает вашему герою 3 ед. здоровья и дает ему <b>«Божественный щит»</b>.', 'Сражается за светлое будущее.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_015.png', 'Daniil Kudriavtsev', 2, 2, 1, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_860', 'time-860', 'Загадочный безликий', '<b>Боевой клич:</b> вы просматриваете 2 случайных <b>секрета</b>. Вы выбираете и разыгрываете один из них, а второй применяется для противника.', 'Я доверяю свои секреты только самым близким друзьям и врагам.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_860.png', 'Jaemin Kim', 2, 2, 2, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_025', 'time-025', 'Сумеречный хрономот', '<b>Боевой клич:</b> вы замешиваете в колоду 2 «Обрывка времени». При взятии: ваш герой получает 3 ед. урона.', 'Вприпрыжку по временным линиям.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_025.png', 'Mauricio Herrera', 2, 4, 4, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'MINION'), (SELECT id FROM rarities WHERE code = 'COMMON'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_810', 'time-810', 'Луносвет: прошлое', 'Наносит 5 ед. урона случайному существу противника. <i>Переходит в настоящее!</i>', 'Луносвет был безупречной жемчужиной Кель''Таласа почти семь тысяч лет. Но затем пришел Король-лич.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_810.png', 'Mooncolony', 4, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_446', 'time-446', 'Вечная крепость', 'Вы <b>раскапываете</b> демона за (5) или больше. Если в вашей колоде нет существ, следующее существо стоит (1).', 'Здесь можно отбыть несколько пожизненных сроков.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_446.png', 'BOSi Studio', 6, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'LEGENDARY'));
INSERT INTO cards (card_code, slug, name, text, flavor_text, image, artist_name, mana_cost, attack, health, durability, armor, collectible, card_set_id, card_type_id, rarity_id) VALUES ('TIME_436', 'time-436', 'Перекресток: прошлое', 'Призывает случайного дракона за (5) или более. <i>Переходит в настоящее!</i>', 'Многие тысячелетия магия скрывала Временной Перекресток и все Драконьи острова от обитателей Азерота — даже от самих драконов.', 'https://art.hearthstonejson.com/v1/render/latest/ruRU/512x/TIME_436.png', 'BOSi Studio', 7, NULL, 3, NULL, NULL, TRUE, (SELECT id FROM card_sets WHERE source_code = 'TIME'), (SELECT id FROM card_types WHERE code = 'LOCATION'), (SELECT id FROM rarities WHERE code = 'EPIC'));
